css:
[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
@keyframes lg-wave{0%{background-position:0% 100%,100% 100%}100%{background-position:100% 100%,0% 100%}}
[data-chat-canvas]{background-image:radial-gradient(ellipse 40% 22% at 50% 100%,rgba(70,220,200,.16),transparent 70%),radial-gradient(ellipse 35% 18% at 50% 100%,rgba(40,170,190,.14),transparent 70%)!important;background-size:180% 100%,180% 100%!important;background-repeat:no-repeat!important;animation:lg-wave 22s ease-in-out infinite alternate}
@media (prefers-reduced-motion:reduce){[data-chat-canvas]{animation:none!important}}
.chat-markdown a{color:#ff9a80!important}
::selection{background:rgba(255,122,92,.3)}
